//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    auto linear = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input;
    };

    auto relu = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input > 0 ? input : 0;
    };


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 

    
    // model input and flattened
    constexpr int flat_size = 9216; 
    std::array<Scalar, flat_size> model_input;

    // normalize input
    for (int i = 0; i < 9216; i++) { model_input[i] = (initial_input[i] - input_mins[i]) / (input_norms[i]); } 

    if (model_input.size() != 9216) { throw std::invalid_argument("Invalid input size. Expected size: 9216"); }

    // Dense, layer 1
    static std::array<Scalar, 8> layer_1_output;
    Dense<Scalar, 8>(
        layer_1_output.data(), model_input.data(),
        weights_1.data(), biases_1.data(),
        9216, linear, 0.0);

    // Dense, layer 2
    static std::array<Scalar, 8> layer_2_output;
    BatchNormalization<Scalar, 8>(
        layer_2_output.data(), layer_1_output.data(),
        gamma_2.data(), beta_2.data(),
        mean_2.data(), variance_2.data(),
        epsilon_2);

    // Dense, layer 3
    static std::array<Scalar, 8> layer_3_output;
    for (int i = 0; i < 8; ++i) {
        relu(layer_3_output[i], layer_2_output[i], 0.0);
    }

    // Dense, layer 4
    static std::array<Scalar, 8> layer_4_output;
    Dense<Scalar, 8>(
        layer_4_output.data(), layer_3_output.data(),
        weights_4.data(), biases_4.data(),
        8, linear, 0.0);

    // Dense, layer 5
    static std::array<Scalar, 8> layer_5_output;
    for (int i = 0; i < 8; ++i) {
        relu(layer_5_output[i], layer_4_output[i], 0.0);
    }

    // Dense, layer 6
    static std::array<Scalar, 9216> layer_6_output;
    Dense<Scalar, 9216>(
        layer_6_output.data(), layer_5_output.data(),
        weights_6.data(), biases_6.data(),
        8, linear, 0.0);



//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    static std::array<Scalar, 9216> model_output;

    for (int i = 0; i < 9216; i++) { model_output[i] = (layer_6_output[i] * output_norms[i]) + output_mins[i]; }

    return model_output;

